-- ============================================================================
-- NLE Seed Questions Part 2A: PHARMACOLOGY (007), ANATOMY (008),
--   MICROBIOLOGY (009), LEADERSHIP & MANAGEMENT (010)
-- 146 questions (two duplicates of nle-seed-data.sql questions removed —
--   the question bank enforces UNIQUE question_text).
-- Run after nle-seed-data.sql and before nle-seed-options-4/5.sql
-- ============================================================================

BEGIN;

INSERT INTO nle_question_bank (id, category_id, question_text, question_type, difficulty, explanation, is_high_yield, is_active, created_at, updated_at) VALUES
-- PHARMACOLOGY (37 questions)
('b0000007-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000007', 'What is the mechanism of action of penicillin antibiotics?', 'MC', 'EASY', 'Penicillins inhibit bacterial cell wall synthesis by binding to penicillin-binding proteins, preventing cross-linking of peptidoglycan, which leads to bacterial cell lysis.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000007', 'What is the therapeutic serum digoxin level?', 'MC', 'MEDIUM', 'The therapeutic digoxin level is 0.5-2.0 ng/mL. Levels above 2.0 ng/mL indicate toxicity, manifested by nausea, visual disturbances (yellow halos), and bradycardia.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000007', 'To which drug class does furosemide (Lasix) belong?', 'MC', 'EASY', 'Furosemide is a loop diuretic that inhibits sodium and chloride reabsorption in the ascending loop of Henle. Its major adverse effect is hypokalemia.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000007', 'What is the antidote for acetaminophen (paracetamol) overdose?', 'MC', 'MEDIUM', 'N-acetylcysteine (Mucomyst) is the antidote for acetaminophen overdose. It replenishes hepatic glutathione stores and prevents liver necrosis when given within 8-10 hours.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000007', 'What is the priority drug for anaphylactic shock?', 'MC', 'MEDIUM', 'Epinephrine is the first-line drug for anaphylaxis. It is given intramuscularly into the anterolateral thigh (0.3-0.5 mg of 1:1000) to cause bronchodilation and vasoconstriction.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000007', 'Which laboratory test monitors the effect of intravenous heparin therapy?', 'MC', 'MEDIUM', 'Heparin is monitored by aPTT (activated partial thromboplastin time). The therapeutic aPTT is 1.5-2.5 times the normal control value (usually 60-80 seconds).', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000007', 'Warfarin (Coumadin) exerts its anticoagulant effect by which mechanism?', 'MC', 'MEDIUM', 'Warfarin is a vitamin K antagonist. It inhibits the synthesis of vitamin K-dependent clotting factors (II, VII, IX, X) in the liver. It is monitored by PT/INR.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000007', 'Which of the following is a classic sign of digoxin toxicity?', 'MC', 'MEDIUM', 'Classic signs of digoxin toxicity include nausea, vomiting, anorexia, visual disturbances (yellow-green halos), and bradycardia. Hypokalemia increases the risk of toxicity.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000007', 'Metformin belongs to which drug class?', 'MC', 'EASY', 'Metformin is a biguanide oral hypoglycemic agent. It decreases hepatic glucose production and increases insulin sensitivity. Its most common side effect is gastrointestinal upset.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000007', 'What is the onset of action of rapid-acting insulin (lispro/aspart)?', 'MC', 'MEDIUM', 'Rapid-acting insulins begin working within 15-30 minutes of subcutaneous injection. They must be given just before meals and peak at 1-2 hours, requiring timely food intake to prevent hypoglycemia.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000007', 'What is the key dietary teaching for a patient taking an MAO inhibitor (MAOI)?', 'MC', 'MEDIUM', 'Patients on MAOIs must avoid tyramine-rich foods (aged cheese, cured meats, fermented foods, red wine) because tyramine combined with MAOIs can cause a hypertensive crisis.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000007', 'What is the antidote for opioid overdose?', 'MC', 'EASY', 'Naloxone (Narcan) is the opioid antagonist that reverses opioid-induced respiratory depression. It has a shorter duration of action than most opioids, so repeat doses may be needed.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000007', 'What is the most serious adverse effect of aminoglycoside antibiotics (gentamicin)?', 'MC', 'MEDIUM', 'Aminoglycosides are nephrotoxic and ototoxic. The nurse must monitor renal function (BUN, creatinine) and hearing/balance, and assess for tinnitus and dizziness.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000007', 'What is the effect of grapefruit juice on certain medications?', 'MC', 'MEDIUM', 'Grapefruit juice inhibits CYP3A4 enzymes in the intestinal wall, increasing serum levels and effects of drugs such as statins (simvaptatin, atorvastatin) and some calcium channel blockers, raising the risk of toxicity. Patients should avoid grapefruit juice with these drugs.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000007', 'Which class of drugs includes albuterol (salbutamol)?', 'MC', 'EASY', 'Albuterol is a short-acting beta-2 adrenergic agonist (SABA) used as a rescue bronchodilator for asthma. It relieves bronchospasm within minutes.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000007', 'What is the correct route for administering nitroglycerin for acute angina?', 'MC', 'EASY', 'Nitroglycerin is given sublingually to bypass first-pass metabolism for rapid effect. The patient should be seated, and the drug may cause headache and hypotension.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000007', 'Which drug must NOT be given intramuscularly to a patient on anticoagulant therapy?', 'MC', 'MEDIUM', 'Patients on anticoagulants should avoid IM injections because of the risk of deep tissue bleeding and hematoma formation. Subcutaneous or oral routes are preferred.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000007', 'Beta-adrenergic blockers (propranolol, metoprolol) produce which effect?', 'MC', 'MEDIUM', 'Beta blockers block beta-adrenergic receptors, decreasing heart rate, contractility, and blood pressure. They are used for hypertension, angina, and heart failure, and must be tapered off to avoid rebound tachycardia.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000007', 'What does the abbreviation PRN mean on a medication order?', 'MC', 'EASY', 'PRN stands for pro re nata, meaning as needed or as the occasion arises. PRN orders specify a condition and a maximum frequency, such as every 4-6 hours as needed for pain.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000007', 'Which nursing action is MOST important before administering any medication?', 'MC', 'MEDIUM', 'The nurse must verify the rights of medication administration and perform a final check against the original physician order, assessing for allergies and contraindications before every dose.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000007', 'What is the correct subcutaneous injection angle for most adults?', 'MC', 'EASY', 'Subcutaneous injections are given at a 45-90 degree angle depending on the amount of subcutaneous tissue. A 90-degree angle is used with a short (5/8 inch) needle and pinched skin fold.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000007', 'Which supplement must a patient taking isoniazid (INH) receive to prevent peripheral neuropathy?', 'MC', 'MEDIUM', 'Isoniazid depletes pyridoxine (vitamin B6), so pyridoxine 25-50 mg daily is co-administered to prevent peripheral neuropathy. Patients also report dark orange urine and avoid alcohol.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000007', 'Which antibiotic class is associated with tendon rupture as a serious adverse effect?', 'MC', 'MEDIUM', 'Fluoroquinolones (ciprofloxacin, levofloxacin) carry a black box warning for tendinitis and tendon rupture, especially the Achilles tendon. Patients should report tendon pain and stop the drug.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000007', 'What is the mechanism of action of acetaminophen (paracetamol)?', 'MC', 'MEDIUM', 'Acetaminophen inhibits prostaglandin synthesis centrally in the hypothalamus, producing antipyresis and analgesia. Unlike NSAIDs, it has minimal anti-inflammatory effect and is not a platelet inhibitor.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000007', 'A patient on warfarin is prescribed aspirin. What does the nurse anticipate?', 'MC', 'MEDIUM', 'Combining warfarin and aspirin greatly increases bleeding risk because both affect hemostasis. The nurse monitors for bleeding (bruising, melena, hematuria) and checks INR more frequently.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000007', 'Which findings suggest lithium toxicity? (Select the best answer)', 'MC', 'HARD', 'Lithium toxicity presents with coarse tremor, nausea, vomiting, diarrhea, ataxia, confusion, slurred speech, and in severe cases seizures and coma. The therapeutic lithium level is 0.6-1.2 mEq/L.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000007', 'Fluoxetine (Prozac) belongs to which drug class?', 'MC', 'EASY', 'Fluoxetine is a selective serotonin reuptake inhibitor (SSRI) used for depression, anxiety, and OCD. Common side effects include nausea, sexual dysfunction, and insomnia; serotonin syndrome can occur with concurrent MAOIs.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000007', 'What is the correct technique for drawing up equal doses of insulin from two vials (regular and NPH)?', 'MC', 'MEDIUM', 'The nurse draws up clear insulin first (regular) before cloudy insulin (NPH) using the sequential withdrawal method (air displacement) or separate syringes to preserve insulin concentration and action.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000007', 'Which instruction should the nurse emphasize for a patient taking corticosteroids long term?', 'MC', 'MEDIUM', 'Patients on long-term corticosteroids must NEVER stop abruptly (adrenal crisis risk), should take the drug with food, and report signs of infection, hyperglycemia, and osteoporosis risk. Calcium and vitamin D are supplemented.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000007', 'What is the first-line medication for status epilepticus?', 'MC', 'MEDIUM', 'Benzodiazepines (lorazepam IV or diazepam) are first-line for status epilepticus because they terminate seizures rapidly. If ineffective, second-line agents such as levetiracetam or fosphenytoin are given.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000007', 'A patient receiving IV vancomycin reports flushing of the face and neck. What is the cause?', 'MC', 'MEDIUM', 'Rapid infusion of vancomycin causes histamine-mediated flushing known as red man syndrome. The drug must be diluted and infused over at least 60 minutes to prevent this reaction.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000007', 'Which route of drug administration avoids first-pass metabolism?', 'MC', 'MEDIUM', 'Sublingual, transdermal, rectal (lower rectum), inhaled, IV, and subcutaneous routes bypass first-pass hepatic metabolism. Oral drugs are extensively metabolized by the liver before systemic circulation.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000007', 'What is the recommended action when a patient misses an oral contraceptive dose?', 'MC', 'MEDIUM', 'For a missed active pill, take it as soon as remembered and the next pill at the usual time (possibly two pills that day); if more than 7 days are missed, use backup contraception for 7 days.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000007', 'What is the mechanism of action of aspirin at low doses?', 'MC', 'MEDIUM', 'Low-dose aspirin (81 mg) irreversibly inhibits cyclooxygenase (COX-1) in platelets, reducing thromboxane A2 and thus platelet aggregation for the platelet lifespan (7-10 days). This is why it is used for cardiovascular prophylaxis.', false, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000007', 'Which route should the nurse use when administering a drug to an unconscious patient?', 'MC', 'MEDIUM', 'Unconscious patients cannot swallow safely, so oral and sublingual routes are contraindicated. IV (if ordered), IM, or rectal routes are used instead to avoid aspiration.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000007', 'A patient on clozapine must undergo regular blood monitoring. Why?', 'MC', 'MEDIUM', 'Clozapine can cause agranulocytosis, a life-threatening drop in white blood cells. Weekly ANC monitoring is required initially, then every 2-4 weeks; patients must report fever and sore throat immediately.', true, true, NOW(), NOW()),
('b0000007-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000007', 'What does the term half-life mean in pharmacology?', 'MC', 'MEDIUM', 'Half-life is the time required for the serum concentration of a drug to decrease by 50%. It determines dosing intervals and the time to reach steady state (usually 4-5 half-lives).', false, true, NOW(), NOW()),
-- ANATOMY & PHYSIOLOGY (37 questions)
('b0000008-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000008', 'How many bones are found in the normal adult human skeleton?', 'MC', 'EASY', 'The adult skeleton contains 206 bones: 80 in the axial skeleton (skull, vertebral column, thoracic cage) and 126 in the appendicular skeleton (limbs and girdles).', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000008', 'What is the largest organ of the human body?', 'MC', 'EASY', 'The skin is the largest organ of the body. It accounts for approximately 15-20% of body weight and functions in protection, thermoregulation, sensation, and vitamin D synthesis.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000008', 'Which muscle is the primary muscle of respiration?', 'MC', 'EASY', 'The diaphragm is the principal muscle of respiration. When it contracts, it descends, increasing thoracic volume and drawing air into the lungs. The intercostals are accessory muscles.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000008', 'Which heart chamber pumps deoxygenated blood to the lungs?', 'MC', 'EASY', 'The right ventricle pumps deoxygenated blood through the pulmonary valve into the pulmonary artery, which carries it to the lungs for gas exchange.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000008', 'What is the longest, heaviest bone in the body?', 'MC', 'EASY', 'The femur (thigh bone) is the longest and heaviest bone. Its fracture is common in older adults with osteoporosis and can cause significant blood loss.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000008', 'Which muscle extends the forearm at the elbow joint?', 'MC', 'MEDIUM', 'The triceps brachii extends the forearm at the elbow. The biceps brachii is the synergist that flexes the forearm, and the brachialis assists in flexion.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000008', 'What is the smallest functional unit of the kidney?', 'MC', 'EASY', 'The nephron is the functional unit of the kidney. Each kidney contains about 1 million nephrons, which perform filtration, reabsorption, secretion, and excretion.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000008', 'Which part of the brainstem controls the basic rhythm of breathing?', 'MC', 'MEDIUM', 'The medulla oblongata contains the respiratory centers that establish the basic rhythm of breathing. The pons modifies breathing rate, and the cerebral cortex allows voluntary control.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000008', 'Where is the pancreas located?', 'MC', 'MEDIUM', 'The pancreas is a retroperitoneal organ located behind the stomach. It has both exocrine functions (digestive enzymes) and endocrine functions (insulin and glucagon from the islets of Langerhans).', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000008', 'Which gland regulates the basal metabolic rate of the body?', 'MC', 'EASY', 'The thyroid gland produces T3 and T4, which regulate basal metabolic rate, growth, and development. Hypothyroidism causes weight gain, fatigue, and cold intolerance; hyperthyroidism causes weight loss and heat intolerance.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000008', 'What type of joint is found in the hip and shoulder?', 'MC', 'EASY', 'The hip and shoulder joints are ball-and-socket (spheroidal) synovial joints, allowing movement in all planes including rotation. They trade stability (hip) for mobility (shoulder).', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000008', 'What is the muscular layer of the heart called?', 'MC', 'EASY', 'The myocardium is the thick muscular layer of the heart responsible for pumping blood. The epicardium is the outer layer and the endocardium lines the chambers and valves.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000008', 'What is the primary function of red blood cells?', 'MC', 'EASY', 'Red blood cells carry oxygen from the lungs to the tissues using hemoglobin and transport some carbon dioxide back to the lungs. They are produced in red bone marrow and live about 120 days.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000008', 'What is the role of platelets (thrombocytes) in hemostasis?', 'MC', 'MEDIUM', 'Platelets form the platelet plug (primary hemostasis) at the site of vessel injury and release clotting factors that support the coagulation cascade, producing a stable clot (secondary hemostasis).', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000008', 'How many lobes does the right lung have, and how many does the left lung have?', 'MC', 'MEDIUM', 'The right lung has 3 lobes (superior, middle, inferior) and the left lung has 2 lobes (superior, inferior) with the cardiac notch to accommodate the heart.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000008', 'Where does gas exchange between air and blood occur?', 'MC', 'EASY', 'Gas exchange occurs in the alveoli, which have thin walls (one cell thick) surrounded by pulmonary capillaries. Oxygen diffuses into the blood and carbon dioxide diffuses out.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000008', 'What is the pacemaker of the heart?', 'MC', 'MEDIUM', 'The sinoatrial (SA) node in the right atrium is the natural pacemaker. It generates 60-100 impulses per minute. If the SA node fails, the AV node takes over at 40-60 impulses per minute.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000008', 'Which valve lies between the left atrium and the left ventricle?', 'MC', 'MEDIUM', 'The mitral (bicuspid) valve lies between the left atrium and left ventricle. The tricuspid valve is on the right side; the aortic and pulmonary semilunar valves exit the ventricles.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000008', 'What is the largest artery in the body?', 'MC', 'EASY', 'The aorta is the largest artery. It arises from the left ventricle, arches, and descends to supply oxygenated blood to the entire body.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000008', 'What is the difference between a tendon and a ligament?', 'MC', 'MEDIUM', 'Tendons attach muscle to bone and transmit the force of muscle contraction. Ligaments attach bone to bone and stabilize joints. Both are dense connective tissue.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000008', 'Which hormone lowers blood glucose levels?', 'MC', 'EASY', 'Insulin, produced by the beta cells of the islets of Langerhans in the pancreas, lowers blood glucose by promoting cellular uptake of glucose. Glucagon (alpha cells) raises blood glucose.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000008', 'Where are the vocal cords located?', 'MC', 'EASY', 'The vocal cords (vocal folds) are located in the larynx, between the thyroid and cricoid cartilages. The larynx also houses the epiglottis, which prevents food from entering the trachea.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000008', 'What is the function of the liver in digestion?', 'MC', 'MEDIUM', 'The liver produces bile, which emulsifies fats in the duodenum. The gallbladder stores and concentrates bile. The liver also detoxifies drugs, metabolizes nutrients, and synthesizes clotting factors.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000008', 'How many cervical vertebrae does the human spine have?', 'MC', 'EASY', 'The human spine has 33 vertebrae: 7 cervical, 12 thoracic, 5 lumbar, 5 fused sacral, and 4 fused coccygeal. The 7 cervical vertebrae support the head.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000008', 'Which cranial nerve carries the sense of smell?', 'MC', 'MEDIUM', 'The olfactory nerve (CN I) carries the sense of smell. Its fibers pass through the cribriform plate of the ethmoid bone to the olfactory bulb. Damage can occur with head trauma.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000008', 'Where is the urinary bladder located and what is its function?', 'MC', 'EASY', 'The urinary bladder is a hollow muscular organ in the pelvic cavity that stores urine. The detrusor muscle contracts during micturition, and the internal sphincter is under autonomic control.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000008', 'What does the term proximal mean in anatomical position?', 'MC', 'MEDIUM', 'Proximal means nearer to the trunk or point of attachment; distal means farther away. Proximal/distal describe the limbs, while superior/inferior and anterior/posterior describe the trunk.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000008', 'Which blood vessels carry blood away from the heart?', 'MC', 'EASY', 'Arteries carry blood away from the heart (usually oxygenated, except the pulmonary artery). Veins carry blood toward the heart. Capillaries connect arterioles and venules for exchange.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000008', 'What is the site of protein synthesis in the cell?', 'MC', 'MEDIUM', 'Protein synthesis occurs on ribosomes, which may be free in the cytoplasm or bound to the rough endoplasmic reticulum. The nucleus contains DNA and directs cellular activity.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000008', 'Which part of the small intestine absorbs most nutrients?', 'MC', 'MEDIUM', 'The jejunum and ileum absorb most nutrients. The duodenum receives chyme, bile, and pancreatic juice and is the primary site of chemical digestion. Villi and microvilli increase surface area.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000008', 'What is the function of the spleen?', 'MC', 'MEDIUM', 'The spleen filters blood (not lymph), removes old red blood cells, stores platelets, and mounts immune responses to blood-borne antigens. It is part of the lymphatic system but contacts lymphocytes via the blood.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000008', 'In which position is the heart located in the thoracic cavity?', 'MC', 'EASY', 'The heart is located in the mediastinum of the thoracic cavity, between the lungs, slightly left of the midline. It sits posterior to the sternum and anterior to the thoracic vertebrae.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000008', 'What is the normal adult respiratory rate?', 'MC', 'EASY', 'The normal adult respiratory rate at rest is 12-20 breaths per minute. Tachypnea is a rate above 20; bradypnea is below 12. respirations are controlled by the medulla oblongata.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000008', 'Which bone protects the brain?', 'MC', 'EASY', 'The skull (cranium) protects the brain. It consists of 8 bones joined by sutures: frontal, 2 parietal, 2 temporal, occipital, sphenoid, and ethmoid.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000008', 'What is the function of the hypothalamus?', 'MC', 'MEDIUM', 'The hypothalamus maintains homeostasis by regulating body temperature, hunger, thirst, sleep, and the pituitary gland. It links the nervous and endocrine systems via the posterior pituitary.', true, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000008', 'Which muscle flexes the elbow and is commonly used for taking blood pressure?', 'MC', 'EASY', 'The biceps brachii flexes the forearm at the elbow and supinates the forearm. The brachialis is the primary flexor; the triceps extends the elbow.', false, true, NOW(), NOW()),
('b0000008-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000008', 'What are the two main divisions of the nervous system?', 'MC', 'MEDIUM', 'The nervous system is divided into the central nervous system (brain and spinal cord) and the peripheral nervous system (somatic and autonomic, which includes sympathetic and parasympathetic divisions).', false, true, NOW(), NOW()),
-- MICROBIOLOGY (37 questions)
('b0000009-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000009', 'What is the causative agent of tuberculosis?', 'MC', 'EASY', 'Mycobacterium tuberculosis is a slow-growing acid-fast bacillus transmitted via airborne droplet nuclei. It is diagnosed by sputum smear (Ziehl-Neelsen stain), culture (Lowenstein-Jensen), and tuberculin skin test.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000009', 'What is the Gram reaction and shape of Staphylococcus aureus?', 'MC', 'MEDIUM', 'Staphylococcus aureus is a Gram-positive coccus arranged in grape-like clusters. It causes abscesses, wound infections, food poisoning, and MRSA is resistant to methicillin.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000009', 'What is the vector of dengue fever?', 'MC', 'EASY', 'Aedes aegypti mosquito, a daytime-biting mosquito, transmits the dengue virus. Prevention focuses on eliminating stagnant water breeding sites, using insecticide-treated nets, and wearing protective clothing.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000009', 'Which culture medium is used to culture Mycobacterium tuberculosis?', 'MC', 'MEDIUM', 'Lowenstein-Jensen (LJ) medium, an egg-based medium containing malachite green, is used to culture M. tuberculosis. Growth takes 2-8 weeks because of the organism slow growth rate.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000009', 'What are the recommended autoclave settings for sterilization?', 'MC', 'MEDIUM', 'Steam under pressure (autoclave) sterilization uses 121 degrees Celsius at 15 psi for 15-20 minutes. This kills all forms of microbial life including bacterial spores.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000009', 'How is rabies transmitted to humans?', 'MC', 'EASY', 'Rabies is transmitted through the bite of an infected animal or contact of infected saliva with broken skin or mucous membranes. The virus travels to the brain via peripheral nerves.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000009', 'Which organism is the most common cause of community-acquired pneumonia?', 'MC', 'MEDIUM', 'Streptococcus pneumoniae is the most common cause of community-acquired pneumonia in adults. It produces rusty-colored sputum and is diagnosed by Gram stain and culture.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000009', 'What is the most common cause of urinary tract infections?', 'MC', 'EASY', 'Escherichia coli, a Gram-negative rod that is normal flora of the colon, causes about 80% of uncomplicated urinary tract infections. Prevention includes adequate hydration and proper perineal hygiene.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000009', 'Which bacteria form endospores that survive boiling and disinfection?', 'MC', 'MEDIUM', 'Clostridium and Bacillus species form endospores. Clostridium tetani, C. difficile, and C. botulinum cause serious infections; endospores require autoclaving (121 C) for destruction.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000009', 'Which stain is used to identify acid-fast organisms?', 'MC', 'MEDIUM', 'The Ziehl-Neelsen (acid-fast) stain uses carbolfuchsin and acid-alcohol decolorization. Acid-fast organisms like Mycobacterium retain the red stain because of mycolic acid in their cell walls.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000009', 'Which organism causes peptic ulcer disease?', 'MC', 'MEDIUM', 'Helicobacter pylori, a Gram-negative spiral bacterium, causes most duodenal and gastric ulcers. It is treated with triple therapy (proton pump inhibitor plus two antibiotics) and tested via urea breath test or stool antigen.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000009', 'What is the difference between an antiseptic and a disinfectant?', 'MC', 'MEDIUM', 'Antiseptics are applied to living tissue (skin, mucous membranes) to reduce microorganisms. Disinfectants are applied to inanimate objects (floors, equipment) and are generally too harsh for skin.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000009', 'How long should handwashing friction be maintained to remove transient flora?', 'MC', 'MEDIUM', 'WHO recommends rubbing all hand surfaces for 40-60 seconds total (including lathering). Handwashing with soap and water for at least 20 seconds of friction removes most transient microorganisms.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000009', 'Which method is used to sterilize heat-sensitive equipment?', 'MC', 'MEDIUM', 'Ethylene oxide gas or hydrogen peroxide plasma sterilization is used for heat-sensitive instruments such as endoscopes. Heat-sensitive items cannot withstand autoclave temperatures.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000009', 'Which vaccine is a live attenuated vaccine?', 'MC', 'MEDIUM', 'MMR, varicella, oral polio (OPV), yellow fever, and BCG are live attenuated vaccines. They are CONTRAINDICATED in pregnancy and immunocompromised persons because they can cause disease.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000009', 'What is a toxoid vaccine?', 'MC', 'MEDIUM', 'Toxoid vaccines use inactivated toxins (toxoids) to induce antitoxin immunity. Examples are tetanus and diphtheria toxoids, commonly combined as DTaP/Td. Boosters are needed for lifelong protection.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000009', 'Which disease requires airborne precautions?', 'MC', 'MEDIUM', 'Airborne precautions are required for TB, measles (rubeola), varicella (chickenpox), and disseminated herpes zoster. These require an AIIR (airborne infection isolation room) and an N95 respirator.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000009', 'How does HIV destroy the immune system?', 'MC', 'MEDIUM', 'HIV infects and destroys CD4+ T helper lymphocytes, progressively weakening cell-mediated immunity. As CD4 count falls below 200 cells/mm3, opportunistic infections and AIDS-defining illnesses develop.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000009', 'Which mosquito vector transmits malaria?', 'MC', 'EASY', 'The female Anopheles mosquito, which bites at night, transmits Plasmodium species. Prevention includes insecticide-treated bed nets, indoor residual spraying, and chemoprophylaxis.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000009', 'What is the mode of transmission of typhoid fever?', 'MC', 'MEDIUM', 'Salmonella typhi spreads via the fecal-oral route through contaminated food and water. Carriers who chronically shed the organism in stool and urine play a major role in transmission.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000009', 'What is a nosocomial (healthcare-associated) infection?', 'MC', 'MEDIUM', 'A nosocomial infection is acquired in a healthcare facility that was not present or incubating at the time of admission. Common sites are the urinary tract, surgical wounds, lungs, and bloodstream.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000009', 'What does sterile technique require?', 'MC', 'MEDIUM', 'Sterile technique eliminates ALL microorganisms, including spores. Only items sterilized within the sterile field and objects above waist level and within arm reach are considered sterile.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000009', 'Which hepatitis virus is transmitted primarily through blood and body fluids and is preventable by vaccine?', 'MC', 'MEDIUM', 'Hepatitis B virus (HBV) spreads through blood, sexual contact, and perinatal transmission. The HBV vaccine is given at birth, 1 month, and 6 months. HCV spreads through blood and has no vaccine.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000009', 'What is the incubation period of measles?', 'MC', 'MEDIUM', 'Measles has an incubation period of 10-14 days (about 14 days to rash). It spreads airborne and by direct contact; droplet precautions and airborne isolation are required.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000025', 'a1000000-0000-0000-0000-000000000009', 'Which organism is the most common cause of bacterial meningitis in adults?', 'MC', 'MEDIUM', 'Neisseria meningitidis and Streptococcus pneumoniae are the most common causes of bacterial meningitis in adults. Meningococcal meningitis can cause a petechial rash and is treated with droplet precautions.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000009', 'What is normal flora (normal microbiota)?', 'MC', 'EASY', 'Normal flora are resident microorganisms that normally inhabit body surfaces without causing disease under normal conditions. They aid digestion (gut flora), produce vitamins K and B, and compete with pathogens.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000009', 'Which infection control practice is the single most effective way to prevent the spread of infection?', 'MC', 'MEDIUM', 'Hand hygiene (handwashing or alcohol-based hand rub) is the single most effective measure to prevent healthcare-associated infections. Hand hygiene should be performed before and after every patient contact.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000009', 'What causes the characteristic foul smell in anaerobic infections?', 'MC', 'MEDIUM', 'Anaerobic bacteria such as Bacteroides and Clostridium produce enzymes and metabolic byproducts that give tissue destruction a distinctive foul odor and putrid discharge.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000009', 'What is the difference between bacteriostatic and bactericidal antibiotics?', 'MC', 'MEDIUM', 'Bacteriostatic antibiotics (tetracycline, chloramphenicol, macrolides) inhibit bacterial growth, allowing host defenses to clear the infection. Bactericidal antibiotics (penicillins, cephalosporins, aminoglycosides) kill bacteria directly.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000009', 'Which syndrome results from the overgrowth of Clostridium difficile after antibiotic therapy?', 'MC', 'MEDIUM', 'C. difficile overgrowth (usually after broad-spectrum antibiotics) causes pseudomembranous colitis with watery diarrhea, abdominal cramps, and fever. Contact precautions with soap and water are required.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000009', 'What is the correct order for removing personal protective equipment (doffing)?', 'MC', 'MEDIUM', 'Doffing order: gloves, goggles/face shield, gown, then mask. The most contaminated items (gloves) are removed first, and the mask (cleanest area) is removed last, followed by hand hygiene.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000009', 'What is the portal of entry for the influenza virus?', 'MC', 'EASY', 'Influenza enters through the respiratory tract via droplet nuclei from coughs and sneezes. Droplet precautions (mask within 3 feet) are used. The virus infects respiratory epithelial cells.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000009', 'What is the purpose of the tuberculin skin test (Mantoux)?', 'MC', 'MEDIUM', 'The tuberculin skin test detects delayed-type hypersensitivity to Mycobacterium tuberculosis antigens. 0.1 mL (5 TU) of PPD is injected intradermally; results are read in 48-72 hours for induration (not redness).', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000009', 'Which serologic test is used to confirm HIV infection?', 'MC', 'MEDIUM', 'Initial screening uses an HIV antibody/antigen (4th generation) test. Positive screens are confirmed with an HIV-1/HIV-2 differentiation immunoassay and NAT (nucleic acid test) in the CDC laboratory testing algorithm.', false, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000009', 'What causes antibiotic resistance?', 'MC', 'MEDIUM', 'Antibiotic resistance results from genetic mutation and selection pressure from inappropriate use: not completing the full course, using antibiotics for viral infections, and prophylactic overuse. Resistant organisms like MRSA and VRE emerge.', true, true, NOW(), NOW()),
('b0000009-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000009', 'Which fungal infection affects the skin, hair, and nails and is spread by contact?', 'MC', 'MEDIUM', 'Dermatophytosis (tinea) is caused by Trichophyton, Microsporum, and Epidermophyton fungi that infect keratinized tissues. Transmission is by direct contact with infected persons, animals, or fomites.', false, true, NOW(), NOW()),
-- LEADERSHIP & MANAGEMENT (36 questions — b0000010-025 "first step in the nursing
-- process?" removed: duplicate of the FUNDAMENTALS question in nle-seed-data.sql)
('b0000010-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000010', 'Which leadership style involves the group in decision making?', 'MC', 'MEDIUM', 'The democratic (participative) leadership style encourages group participation in decision making while the leader retains final authority. It increases job satisfaction and staff commitment.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000010', 'What is the autocratic (authoritarian) leadership style?', 'MC', 'MEDIUM', 'Autocratic leadership makes decisions independently with minimal group input. It is efficient in emergencies and crisis situations but can lower staff morale and satisfaction when used routinely.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000010', 'Which leadership style gives group complete freedom with minimal leader involvement?', 'MC', 'MEDIUM', 'The laissez-faire (hands-off) style gives subordinates maximum freedom with little guidance. It often leads to role ambiguity, conflict, and poor productivity, and is generally the least effective style.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000010', 'What is the first step in the delegation process?', 'MC', 'MEDIUM', 'Delegation begins with identifying the appropriate task to delegate (right task), then selecting the right person with the competence to perform it, followed by clear communication and supervision.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000010', 'What are the six rights of delegation?', 'MC', 'MEDIUM', 'The six rights are: right task, right circumstance, right person, right direction/communication, right supervision/evaluation, and right time. The delegator remains accountable for the decision to delegate.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000010', 'Who remains legally accountable for tasks delegated to an unlicensed assistive personnel?', 'MC', 'MEDIUM', 'The registered nurse who delegates retains accountability for the delegation decision and for supervising the outcome. The UAP performs the task but the RN is answerable for the result.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000010', 'What is the first step in resolving conflict between two staff members?', 'MC', 'MEDIUM', 'The first step is to listen to each party individually in a private setting to understand both perspectives. The nurse manager then identifies the source of conflict and seeks a mutually acceptable solution.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000010', 'Which principle states that 80% of effects come from 20% of causes?', 'MC', 'MEDIUM', 'The Pareto principle (80/20 rule) states that roughly 80% of effects come from 20% of causes. It is used in quality improvement to prioritize the most impactful problems.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000009', 'a1000000-0000-0000-0000-000000000010', 'What is the Plan-Do-Study-Act (PDSA) cycle used for?', 'MC', 'MEDIUM', 'PDSA (Deming cycle) is a continuous quality improvement model: Plan a change, Do it on a small scale, Study the results, Act to adopt/adapt/reject. It supports iterative testing before full implementation.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000010', 'a1000000-0000-0000-0000-000000000010', 'What is the concept of Magnet Hospital recognition?', 'MC', 'MEDIUM', 'Magnet recognition (ANCC) honors healthcare organizations that demonstrate nursing excellence, high-quality outcomes, and a healthy work environment that recruits and retains professional nurses.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000011', 'a1000000-0000-0000-0000-000000000010', 'Which type of power comes from a person position or title?', 'MC', 'MEDIUM', 'Legitimate (positional) power derives from formal authority of the role. French and Raven identified five bases: legitimate, reward, coercive, expert, and referent power.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000012', 'a1000000-0000-0000-0000-000000000010', 'Which type of power is based on specialized knowledge and skill?', 'MC', 'MEDIUM', 'Expert power comes from a person knowledge, skills, and competence. It is considered one of the most effective sources of influence in clinical nursing practice and shared governance.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000013', 'a1000000-0000-0000-0000-000000000010', 'According to Maslow hierarchy, which need must be met before self-actualization?', 'MC', 'EASY', 'Maslow hierarchy: physiological, safety, love/belonging, esteem, then self-actualization. In a hospital, basic physiologic needs (airway, nutrition) and safety must be addressed before higher-level needs.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000014', 'a1000000-0000-0000-0000-000000000010', 'According to Herzberg two-factor theory, which factor causes job satisfaction?', 'MC', 'MEDIUM', 'Herzberg classified hygiene factors (salary, working conditions, policies) as preventing dissatisfaction, while motivators (achievement, recognition, responsibility, growth) create true satisfaction.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000015', 'a1000000-0000-0000-0000-000000000010', 'Which management function involves setting goals and determining how to achieve them?', 'MC', 'MEDIUM', 'Planning is the first function of management: setting objectives and determining the actions and resources needed. The other functions are organizing, staffing, directing, and controlling.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000016', 'a1000000-0000-0000-0000-000000000010', 'What is the purpose of an organizational chart?', 'MC', 'EASY', 'An organizational chart shows the structure of the organization, the hierarchy of authority, reporting relationships, and lines of communication between positions and departments.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000017', 'a1000000-0000-0000-0000-000000000010', 'In triage, how are patients categorized for priority treatment?', 'MC', 'MEDIUM', 'Triage prioritizes patients by severity and probability of survival, not by arrival order. In disaster triage, START uses tags: Immediate (red), Delayed (yellow), Minor (green), and Dead (black).', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000018', 'a1000000-0000-0000-0000-000000000010', 'What is the main purpose of shared governance in nursing?', 'MC', 'MEDIUM', 'Shared governance gives nurses decision-making authority through unit-based councils and committees (practice, education, research, quality). It increases empowerment, accountability, and professional autonomy.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000019', 'a1000000-0000-0000-0000-000000000010', 'What does SBAR stand for in clinical communication?', 'MC', 'EASY', 'SBAR stands for Situation, Background, Assessment, Recommendation. It is a standardized framework for urgent communication between healthcare providers to prevent communication errors.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000020', 'a1000000-0000-0000-0000-000000000010', 'What is a sentinel event?', 'MC', 'MEDIUM', 'A sentinel event is an unexpected occurrence involving death or serious physical or psychological injury, such as wrong-site surgery or patient suicide. It requires immediate investigation and root cause analysis.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000010', 'What is the purpose of a root cause analysis (RCA)?', 'MC', 'MEDIUM', 'RCA is a systematic, non-punitive process that identifies the underlying (root) causes of an adverse event or near miss so that system-level changes can prevent recurrence.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000010', 'What does a just culture promote?', 'MC', 'MEDIUM', 'A just culture distinguishes human error (console), at-risk behavior (coach), and reckless behavior (discourage). It encourages error reporting without fear of blame while maintaining accountability.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000010', 'What is the primary purpose of an incident report?', 'MC', 'MEDIUM', 'An incident (occurrence) report is used for quality improvement and risk management to identify system problems. It is NOT part of the medical record and is NOT used to assign blame.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000010', 'Which budget type includes salaries, utilities, and supplies of a specific department?', 'MC', 'MEDIUM', 'An operating budget covers day-to-day expenses (salaries, supplies, utilities) for a department. A capital budget covers major purchases (equipment, building improvements) of $5,000 or more.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000026', 'a1000000-0000-0000-0000-000000000010', 'Which Lewin model stage involves preparing the change?', 'MC', 'MEDIUM', 'Lewin three-stage model: Unfreezing (creating readiness by challenging current practices), Change (implementing new behaviors), and Refreezing (reinforcing and stabilizing the change).', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000027', 'a1000000-0000-0000-0000-000000000010', 'What is the role of the charge nurse in a shift?', 'MC', 'MEDIUM', 'The charge nurse is a first-line manager who coordinates daily unit operations: patient assignment, staffing, resource allocation, problem solving, and serving as a resource and role model for the team.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000028', 'a1000000-0000-0000-0000-000000000010', 'What is the purpose of an inservice education program?', 'MC', 'EASY', 'Inservice education provides ongoing staff development within the institution to update knowledge and skills, maintain competence, address policy changes, and improve patient outcomes.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000029', 'a1000000-0000-0000-0000-000000000010', 'Which communication method is most effective for ensuring accountability during shift changes?', 'MC', 'MEDIUM', 'Bedside shift report (handoff at the bedside with the patient involved) improves accuracy, engages patients in their care, and clarifies expectations between off-going and oncoming nurses.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000030', 'a1000000-0000-0000-0000-000000000010', 'What is the span of control in management?', 'MC', 'MEDIUM', 'Span of control refers to the number of subordinates a manager supervises. A span of 5-8 is often cited as ideal; a wider span means fewer management levels (flat structure).', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000031', 'a1000000-0000-0000-0000-000000000010', 'What is total quality management (TQM)?', 'MC', 'MEDIUM', 'TQM is a comprehensive approach focused on continuous improvement, customer satisfaction, and total employee involvement in improving processes, products, and services. Prevention of errors is emphasized over inspection.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000032', 'a1000000-0000-0000-0000-000000000010', 'Which staffing pattern places one RN with several LPNs and nursing aides?', 'MC', 'MEDIUM', 'Team nursing uses an interdisciplinary team led by an RN who delegates to LPNs and UAPs based on patient needs and staff competence, coordinating total care for a group of patients.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000033', 'a1000000-0000-0000-0000-000000000010', 'What is the best leadership style during a code blue or disaster?', 'MC', 'MEDIUM', 'An autocratic (directive) style is most effective in emergencies when rapid decisions and clear, single-source authority are needed. Time for participation is not available in life-threatening situations.', true, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000034', 'a1000000-0000-0000-0000-000000000010', 'Which type of power is based on the ability to punish?', 'MC', 'MEDIUM', 'Coercive power relies on the ability to impose punishment or negative consequences (demerits, termination). It may secure compliance but typically breeds resentment and resistance.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000035', 'a1000000-0000-0000-0000-000000000010', 'What is the purpose of utilization review in a hospital?', 'MC', 'MEDIUM', 'Utilization review evaluates the necessity, appropriateness, and efficiency of healthcare services (including length of stay and level of care) to optimize resources and support quality outcomes and reimbursement.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000036', 'a1000000-0000-0000-0000-000000000010', 'What is the primary characteristic of an effective team?', 'MC', 'MEDIUM', 'Effective teams show open communication, mutual trust and respect, shared goals, clear roles, and collaborative problem solving. Psychological safety allows members to speak up about concerns.', false, true, NOW(), NOW()),
('b0000010-0000-0000-0000-000000000037', 'a1000000-0000-0000-0000-000000000010', 'Which managerial skill is most important at the executive level?', 'MC', 'MEDIUM', 'Conceptual skills (vision, strategic thinking, seeing the organization as a whole) are most important for top managers. Human/interpersonal skills matter at all levels; technical skill is most critical for first-line managers.', false, true, NOW(), NOW());

COMMIT;
